@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap');
:root{--ink:#283c37;--muted:#87928a;--cream:#f7f3e9;--paper:#fffdf7;--line:#e9e3d6;--green:#597a60;--green-dark:#3e6149;--sage:#e5eee3;--pink:#f5e3db;--gold:#eab95e;--shadow:0 12px 30px #65533b0c}
*{box-sizing:border-box}body{margin:0;background:#f2ecdf;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px;min-height:100vh;background-image:radial-gradient(#c9b99a24 .7px,transparent .7px);background-size:7px 7px}button{font:inherit;color:inherit;cursor:pointer}.game-shell{max-width:1220px;margin:auto;padding:20px 30px 14px}.topbar{height:60px;display:flex;align-items:center;justify-content:space-between;margin-bottom:17px}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-family:Fraunces,serif;font-size:23px;font-weight:700;letter-spacing:-.8px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:12px;background:#dce9d9;color:#527355;font-family:serif;font-size:23px}.brand-light{font-weight:500;color:#83917f;margin-left:4px}.top-stats{display:flex;gap:9px}.stat-pill{height:36px;border:1px solid #e5dfd1;background:#fffdf8;border-radius:30px;display:flex;align-items:center;gap:7px;padding:0 13px;font-size:13px;font-weight:700;box-shadow:0 2px 6px #66553308}.stat-icon{font-size:15px;color:#71906f}.cash .stat-icon{color:#c99e45}.rep .stat-icon{color:#de8c79}.stat-pill small{font-size:10px;color:var(--muted);font-weight:600;margin-left:-4px}.icon-btn{border:1px solid var(--line);background:#fffdf8;border-radius:11px;width:36px;height:36px;font-size:18px;color:#71816f}.panel{background:var(--paper);border:1px solid #e9e2d4;border-radius:16px;box-shadow:var(--shadow)}.game-grid{display:grid;grid-template-columns:1.55fr 1fr;gap:16px;align-items:stretch}.market-panel{padding:21px 22px 0;overflow:hidden}.panel-heading,.section-title{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.35px;color:#9aa094;margin:0 0 5px}.panel-heading h1,.section-title h2{font-family:Fraunces,serif;letter-spacing:-.6px;margin:0;color:#30433a}.panel-heading h1{font-size:25px}.sun-doodle{font-family:sans-serif;color:#e3b45c;font-size:18px;vertical-align:top}.weather{display:flex;align-items:center;gap:8px;color:#d4a348}.weather>span{font-size:25px}.weather b,.weather small{display:block}.weather b{font-size:10px;color:#5a6858}.weather small{font-size:9px;color:#a6a69b;margin-top:3px}.market-scene{height:270px;margin:14px -22px 0;position:relative;overflow:hidden;background:linear-gradient(#e9f1e7 0%,#f2eddb 67%,#d7d0bc 67%,#d7d0bc 100%);isolation:isolate}.scene-sky{position:absolute;inset:0 0 33%;background:linear-gradient(#dcece7,#f4f0db)}.sun{position:absolute;right:13%;top:24px;width:44px;height:44px;border-radius:50%;background:#f5d992;box-shadow:0 0 0 10px #f4d9923b}.cloud{position:absolute;width:62px;height:17px;border-radius:20px;background:#fffdf2;opacity:.72;top:34px;left:13%;filter:drop-shadow(0 5px 5px #8eaa9b15)}.cloud:before,.cloud:after{content:'';position:absolute;background:inherit;border-radius:50%;bottom:3px}.cloud:before{width:26px;height:26px;left:10px}.cloud:after{width:20px;height:20px;left:30px}.cloud-two{left:auto;top:69px;right:27%;transform:scale(.72)}.string-lights{position:absolute;left:7%;right:7%;top:8px;text-align:center;color:#8aa08e;font-size:11px;letter-spacing:12px;opacity:.85}.shop-sign{position:absolute;z-index:3;top:24px;left:50%;transform:translateX(-50%);width:170px;height:41px;border-radius:5px 5px 2px 2px;background:#fff8e9;box-shadow:0 4px 0 #d9c9a9;border:1px solid #e8d8ba;display:flex;align-items:center;justify-content:center;gap:7px;color:#71876c}.shop-sign span{font-size:18px}.shop-sign b{font-family:Fraunces,serif;letter-spacing:1px;font-size:11px}.shop-sign small{position:absolute;bottom:2px;letter-spacing:1.7px;font-size:6px;color:#bc9b66}.shop-roof{position:absolute;z-index:2;top:73px;left:50%;transform:translateX(-50%);width:76%;max-width:520px;height:37px;background:#c87f66;display:flex;justify-content:space-around;overflow:hidden;border-radius:4px 4px 0 0;box-shadow:0 5px 0 #a96a5a}.shop-roof i{height:100%;width:9%;background:#f5e5ce;border-radius:0 0 12px 12px}.shop-roof i:nth-child(even){background:#cf876f}.shop-front{position:absolute;z-index:1;top:109px;left:50%;transform:translateX(-50%);height:115px;width:68%;max-width:460px;background:#d8b996;border:8px solid #f4e3c9;border-top:0;box-shadow:inset 0 0 0 2px #caa982}.window{position:absolute;left:8%;top:16px;width:37%;height:74px;background:linear-gradient(135deg,#d9eee8,#bfd8d0);border:6px solid #fff3dd;box-shadow:0 0 0 1px #b99976;overflow:hidden}.window:after{content:'';position:absolute;left:50%;top:0;bottom:0;border-left:3px solid #fff3dd}.window-glint{position:absolute;inset:7px 8px;background:linear-gradient(130deg,#ffffff70 0 18%,transparent 20% 65%,#ffffff50 67% 71%,transparent 73%)}.shelf{position:absolute;bottom:13px;left:4px;right:4px;height:26px;border-bottom:4px solid #b89470;display:flex;align-items:flex-end;justify-content:space-around;font-size:15px;z-index:1}.window-boxes{position:absolute;bottom:4px;left:5px;width:23px;height:8px;background:#d9b179;box-shadow:31px -3px #c89473,52px 1px #9ead89}.door{position:absolute;right:10%;top:12px;width:25%;height:95px;background:#8c7258;border:6px solid #fff2dd;border-bottom:0;box-shadow:inset 0 0 0 2px #bb9c78}.door-window{position:absolute;top:7px;left:6px;right:6px;height:40px;background:linear-gradient(130deg,#d5e9dd,#a9c5b7);border:2px solid #d5c1a0}.knob{position:absolute;right:7px;bottom:23px;width:5px;height:5px;background:#e6c46f;border-radius:50%}.front-vine{position:absolute;right:1%;top:12px;color:#66836a;font-size:38px;transform:rotate(-26deg)}.awning-shadow{position:absolute;z-index:3;top:143px;left:16%;width:68%;max-width:460px;height:10px;background:#775f4930;filter:blur(4px)}.planter{position:absolute;z-index:4;bottom:42px;font-size:20px;filter:drop-shadow(0 3px 1px #63533a20)}.planter-left{left:10%}.planter-right{right:10%}.sidewalk{position:absolute;left:0;right:0;bottom:0;height:35px;background:repeating-linear-gradient(90deg,transparent 0 106px,#b8b09f 107px 108px),linear-gradient(#d8d1c0,#c9c1af);border-top:2px solid #c1b9a7}.customer-lane{position:absolute;z-index:5;bottom:13px;left:22%;right:22%;height:58px;display:flex;align-items:flex-end;justify-content:center;gap:10px;pointer-events:none}.customer{font-size:29px;animation:arrive .4s ease-out;filter:drop-shadow(0 3px 1px #55452b28)}@keyframes arrive{from{transform:translateY(25px);opacity:0}to{transform:translateY(0);opacity:1}}.scene-caption{position:absolute;z-index:6;left:12px;bottom:8px;padding:6px 9px;border-radius:20px;background:#fffdf0d9;font-size:9px;color:#657263;display:flex;align-items:center;gap:6px;box-shadow:0 2px 7px #53472c13}.live-dot,.status-dot{width:6px;height:6px;border-radius:50%;background:#7fa57d;display:inline-block}.market-footer{height:44px;display:flex;align-items:center;gap:16px;font-size:10px;color:#999b90}.open-status{display:flex;align-items:center;gap:6px;font-size:9px;color:#648367;font-weight:700;letter-spacing:.7px}.visitors{white-space:nowrap}.visitors span{font-size:12px}.visitors b{color:#52634f}.text-button{border:0;background:none;color:#718a6d;font-size:10px;font-weight:700;padding:5px}.text-button span{font-size:14px;margin-left:3px}.market-footer .text-button{margin-left:auto}
.side-column{display:grid;grid-template-rows:auto 1fr;gap:16px}.orders-panel,.craft-panel,.inventory-panel,.progress-panel{padding:17px 18px}.section-title h2{font-size:17px}.wish-icon,.craft-icon,.goal-icon{font-size:23px;color:#dc9985}.craft-icon{color:#a68e67}.orders-list{display:flex;gap:8px;margin-top:13px}.order-card{border:1px solid #eee6d9;border-radius:10px;background:#fffdf8;padding:9px 10px;flex:1;min-width:0;position:relative}.order-top{display:flex;justify-content:space-between;align-items:center;gap:3px}.order-item{font-weight:700;font-size:10px;white-space:nowrap}.order-emoji{font-size:16px}.order-reward{font-weight:700;color:#628064;font-size:10px;margin-top:5px}.order-card small{display:block;color:#9c9d92;font-size:8px;margin-top:2px;white-space:nowrap}.order-progress{height:3px;background:#eeeae0;border-radius:4px;margin-top:7px;overflow:hidden}.order-progress i{height:100%;display:block;background:#9bb797;border-radius:4px}.craft-panel{display:flex;flex-direction:column;min-height:0}.recipe-list{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:11px 0 12px}.recipe{display:flex;align-items:center;gap:7px;text-align:left;border:1px solid #eee8dc;background:#fffefa;border-radius:10px;padding:8px;transition:.18s;min-width:0}.recipe:hover:not(:disabled){transform:translateY(-2px);border-color:#b9cbb4;box-shadow:0 4px 10px #65775114}.recipe:disabled{opacity:.48;cursor:not-allowed}.recipe-emoji{font-size:20px}.recipe-copy{min-width:0;flex:1}.recipe-copy b{font-size:10px;display:block;white-space:nowrap}.recipe-copy small{font-size:8px;color:#92968b;white-space:nowrap;display:block;margin-top:3px}.recipe-price{font-size:9px;color:#668166;font-weight:700;align-self:flex-start;white-space:nowrap}.inventory-bar{border-top:1px solid #eee9df;padding-top:9px;display:flex;justify-content:space-between;align-items:center;color:#8b9187;font-size:8px;font-weight:700;letter-spacing:1px}.inventory-bar .text-button{font-size:9px}.supplies{display:flex;gap:6px;margin-top:6px}.supply{background:#f5f2e9;border-radius:7px;padding:5px 7px;font-size:9px;color:#737b6d;flex:1;display:flex;justify-content:space-between;align-items:center;white-space:nowrap}.supply b{color:#4b604b;font-size:10px}
.bottom-grid{display:grid;grid-template-columns:1.55fr 1fr;gap:16px;margin-top:16px}.inventory-title{margin-bottom:13px}.count-badge{display:inline-grid;place-items:center;background:#edf1e9;color:#6b8165;border-radius:20px;font:700 9px 'DM Sans';width:19px;height:19px;vertical-align:2px;margin-left:4px}.sell-all{border:1px solid #dbe5d6;background:#eff5ec;color:#62805f;border-radius:8px;padding:7px 10px;font-weight:700;font-size:9px}.sell-all span{font-size:13px;margin-left:4px}.goods-list{min-height:58px;display:flex;gap:8px;overflow-x:auto;padding-bottom:2px}.empty-shelf{width:100%;display:grid;place-items:center;color:#a4a69a;font-size:10px;border:1px dashed #e6e1d6;border-radius:9px;min-height:54px}.goods-card{flex:1;min-width:115px;max-width:190px;display:flex;align-items:center;gap:8px;border:1px solid #eee7dc;background:#fffefa;border-radius:9px;padding:7px}.goods-emoji{font-size:22px}.goods-info{min-width:0;flex:1}.goods-info b{font-size:9px;display:block;white-space:nowrap}.goods-info small{color:#92968a;font-size:8px;display:block;margin-top:3px}.goods-sell{border:0;border-radius:6px;background:#edf4e9;color:#638060;padding:5px;font-weight:700;font-size:8px;white-space:nowrap}.goal-list{margin-top:11px;display:grid;gap:9px}.goal-row{display:flex;align-items:center;gap:8px}.goal-check{width:16px;height:16px;border:1px solid #d8dfd3;border-radius:50%;display:grid;place-items:center;font-size:9px;color:white;flex:none}.goal-row.done .goal-check{background:#83a17d;border-color:#83a17d}.goal-copy{flex:1}.goal-copy b{font-size:9px;font-weight:600;display:block}.goal-copy small{font-size:8px;color:#9b9e92}.goal-reward{font-size:8px;color:#8a987e;font-weight:700;white-space:nowrap}footer{height:34px;display:flex;align-items:end;justify-content:space-between;color:#a1a094;font-size:9px;padding:0 3px}footer span:first-child{font-family:Fraunces,serif;font-size:11px;color:#7c8878}.reset-link{border:0;background:none;color:#a5a297;font-size:9px;padding:0}.toast{position:fixed;z-index:20;left:50%;bottom:24px;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#304b3d;color:#fffdf6;padding:11px 17px;border-radius:30px;box-shadow:0 8px 24px #26382c33;font-size:12px;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{display:none;position:fixed;inset:0;background:#25382e77;z-index:30;place-items:center;padding:18px}.modal-backdrop.show{display:grid}.modal{width:min(420px,100%);padding:24px;box-shadow:0 20px 60px #25382e44}.modal h2{font:600 25px Fraunces;margin:4px 0 7px}.modal p{font-size:12px;color:#788277;line-height:1.55}.modal-options{display:grid;gap:9px;margin:18px 0}.upgrade-option{display:flex;align-items:center;gap:10px;border:1px solid var(--line);background:#fffefa;border-radius:10px;padding:11px;text-align:left}.upgrade-option:hover:not(:disabled){border-color:#abc1a5;background:#f7fbf4}.upgrade-option:disabled{opacity:.5;cursor:not-allowed}.upgrade-option>span:first-child{font-size:23px}.upgrade-option div{flex:1}.upgrade-option b{display:block;font-size:11px}.upgrade-option small{font-size:9px;color:#92978a}.upgrade-option strong{font-size:10px;color:#648160}.modal-close{border:0;background:#edf2e9;color:#62775c;border-radius:8px;padding:9px 14px;font-weight:700;font-size:11px}.modal-actions{display:flex;justify-content:flex-end;gap:8px}.danger-btn{border:1px solid #ecd7d0;background:#fbf0ec;color:#a46b5d;border-radius:8px;padding:9px 12px;font-weight:700;font-size:11px}
@media(max-width:850px){.game-shell{padding:14px 16px}.game-grid,.bottom-grid{grid-template-columns:1fr}.side-column{grid-template-columns:1fr 1fr;grid-template-rows:auto}.market-scene{height:260px}.craft-panel{min-height:220px}.orders-panel{min-height:180px}.bottom-grid{margin-top:14px}}
@media(max-width:560px){.game-shell{padding:10px 10px 12px}.topbar{height:49px;margin-bottom:11px}.brand{font-size:18px;gap:7px}.brand-mark{height:30px;width:30px}.top-stats{gap:4px}.stat-pill{height:31px;padding:0 8px;gap:4px;font-size:11px}.stat-icon{font-size:12px}.icon-btn{width:31px;height:31px}.game-grid{gap:10px}.market-panel{padding:15px 13px 0}.panel-heading h1{font-size:22px}.weather{gap:4px}.weather>span{font-size:20px}.weather b{font-size:9px}.weather small{font-size:8px}.market-scene{height:240px;margin:12px -13px 0}.shop-roof{width:86%}.shop-front{width:78%}.planter-left{left:4%}.planter-right{right:4%}.customer-lane{left:17%;right:17%;gap:3px}.market-footer{gap:8px;height:40px}.market-footer .text-button{font-size:9px}.visitors{font-size:9px}.side-column{grid-template-columns:1fr;gap:10px}.orders-panel,.craft-panel,.inventory-panel,.progress-panel{padding:14px}.orders-panel{min-height:auto}.craft-panel{min-height:0}.orders-list{margin-top:9px}.order-card{padding:8px}.bottom-grid{gap:10px;margin-top:10px}.goods-card{min-width:125px}.progress-panel{padding-bottom:17px}footer{font-size:8px;align-items:center;margin-top:6px}footer span:nth-child(2){display:none}.scene-caption{font-size:8px}.shop-sign{width:155px}.recipe{padding:7px 6px}.recipe-emoji{font-size:18px}.supply{font-size:8px;padding:5px}.weather small{max-width:80px}}

const recipes = [
  {id:'candle',name:'Honey candle',emoji:'🕯️',price:18,needs:{wax:2,herbs:1},time:'1 min'},
  {id:'plush',name:'Pocket plushie',emoji:'🧸',price:26,needs:{cloth:2,thread:1},time:'2 min'},
  {id:'scarf',name:'Cloud-soft scarf',emoji:'🧣',price:22,needs:{wool:2,thread:1},time:'1 min'},
  {id:'jam',name:'Berry jam',emoji:'🍓',price:15,needs:{berries:2,jar:1},time:'1 min'},
  {id:'bouquet',name:'Wildflower bunch',emoji:'💐',price:20,needs:{flowers:2,thread:1},time:'1 min'},
  {id:'mug',name:'Mushroom mug',emoji:'🍄',price:32,needs:{clay:2,glaze:1},time:'3 min'}
];
const supplyData = {
  wax:{name:'Beeswax',icon:'🐝'},herbs:{name:'Herbs',icon:'🌿'},cloth:{name:'Cotton',icon:'🧵'},thread:{name:'Thread',icon:'🪡'},
  wool:{name:'Wool',icon:'🐑'},berries:{name:'Berries',icon:'🫐'},jar:{name:'Jars',icon:'🫙'},flowers:{name:'Flowers',icon:'🌼'},clay:{name:'Clay',icon:'🪨'},glaze:{name:'Glaze',icon:'🎨'}
};
const costPerSupply=4;
const initialState={cash:70,day:1,rep:0,supplies:{wax:4,herbs:3,cloth:4,thread:4,wool:3,berries:4,jar:3,flowers:3,clay:3,glaze:2},goods:[],orders:[],visitors:0,sold:0,made:0,upgrades:{},lastOrder:0};
let state=loadState(), toastTimer, customerTimer, orderTimer;
const $=s=>document.querySelector(s);
function loadState(){try{const saved=JSON.parse(localStorage.getItem('littleWorkshopSave'));if(saved)return {...structuredClone(initialState),...saved,supplies:{...initialState.supplies,...saved.supplies},upgrades:{...initialState.upgrades,...saved.upgrades}}}catch(e){}return structuredClone(initialState)}
function save(){localStorage.setItem('littleWorkshopSave',JSON.stringify(state))}
const money=n=>'$'+Math.floor(n);
function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function setup(){
  if(!state.orders.length)makeOrders();
  render();
  customerTimer=setInterval(addCustomer,9000);
  orderTimer=setInterval(()=>{if(state.orders.length<3){addOrder();renderOrders()}},45000);
  $('#recipe-list').addEventListener('click',e=>{const btn=e.target.closest('[data-craft]');if(btn)craft(btn.dataset.craft)});
  $('#goods-list').addEventListener('click',e=>{const btn=e.target.closest('[data-sell]');if(btn)sellGood(btn.dataset.sell)});
  $('#buy-supplies').onclick=showRestock;
  $('#sell-all').onclick=sellAll;
  $('#next-day').onclick=endDay;
  $('#sound-toggle').onclick=()=>notify('A little bird sings somewhere nearby. ♫');
  $('#reset-game').onclick=confirmReset;
  $('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
}
function render(){
  $('#cash').textContent=money(state.cash);$('#day-label').textContent='Day '+state.day;$('#rep').textContent=state.rep;
  $('#visitor-count').textContent=state.visitors;$('#stock-count').textContent=state.goods.length;
  renderOrders();renderRecipes();renderSupplies();renderGoods();renderGoals();
}
function makeOrders(){state.orders=[];for(let i=0;i<3;i++)addOrder(false);}
function addOrder(fresh=true){
  const available=recipes.filter(r=>!state.orders.some(o=>o.recipe===r.id));
  const recipe=available[Math.floor(Math.random()*available.length)]||recipes[Math.floor(Math.random()*recipes.length)];
  const order={id:Date.now()+Math.random(),recipe:recipe.id,reward:Math.ceil(recipe.price*1.35),customer:['Mina','Theo','Poppy','Jun','Clover','Milo'][Math.floor(Math.random()*6)],emoji:['👩🏻‍🌾','🧑🏽‍🎨','👵🏻','🧔🏽','👩🏾‍🦱','🧑🏻‍🦰'][Math.floor(Math.random()*6)]};
  state.orders.push(order);if(fresh&&state.orders.length===1)state.lastOrder=Date.now();save();
}
function renderOrders(){
  $('#orders-list').innerHTML=state.orders.length?state.orders.slice(0,3).map(o=>{const r=recipes.find(x=>x.id===o.recipe);const have=state.goods.filter(g=>g.recipe===o.recipe).length;return `<article class="order-card"><div class="order-top"><span class="order-item">${r.name}</span><span class="order-emoji">${o.emoji}</span></div><div class="order-reward">${money(o.reward)} <small>+ a happy customer</small></div><div class="order-progress"><i style="width:${have?'100':'0'}%"></i></div></article>`}).join(''):'<div class="empty-shelf">No wishes just now. New neighbors will stop by soon!</div>';
}
function renderRecipes(){
  $('#recipe-list').innerHTML=recipes.map(r=>{const can=Object.entries(r.needs).every(([k,n])=>state.supplies[k]>=n);return `<button class="recipe" data-craft="${r.id}" ${can?'':'disabled'} title="${can?'Make '+r.name:'Not enough supplies'}"><span class="recipe-emoji">${r.emoji}</span><span class="recipe-copy"><b>${r.name}</b><small>${Object.entries(r.needs).map(([k,n])=>`${supplyData[k].icon}${n}`).join(' ')} · ${r.time}</small></span><span class="recipe-price">${money(r.price)}</span></button>`}).join('');
}
function renderSupplies(){ $('#supplies').innerHTML=Object.entries(state.supplies).map(([k,n])=>`<div class="supply" title="${supplyData[k].name}"><span>${supplyData[k].icon} ${supplyData[k].name}</span><b>${n}</b></div>`).join('') }
function renderGoods(){
  const shelf=$('#goods-list');
  shelf.innerHTML=state.goods.length?state.goods.map(g=>{const r=recipes.find(x=>x.id===g.recipe);return `<div class="goods-card"><span class="goods-emoji">${r.emoji}</span><span class="goods-info"><b>${r.name}</b><small>Handmade · ${money(r.price)}</small></span><button class="goods-sell" data-sell="${g.id}">Sell</button></div>`}).join(''):'<div class="empty-shelf">Your shelf is waiting for its first handmade treasure ✿</div>';
}
function goals(){return [
  {id:'make3',label:'Make 3 lovely things',sub:`${Math.min(state.made,3)} of 3 made`,done:state.made>=3,reward:'$20'},
  {id:'sell2',label:'Find homes for 2 creations',sub:`${Math.min(state.sold,2)} of 2 sold`,done:state.sold>=2,reward:'+2 rep'},
  {id:'rep5',label:'Become a neighborhood favorite',sub:`${Math.min(state.rep,5)} of 5 rep`,done:state.rep>=5,reward:'✿'}
]}
function renderGoals(){ $('#goal-list').innerHTML=goals().map(g=>`<div class="goal-row ${g.done?'done':''}"><span class="goal-check">${g.done?'✓':''}</span><span class="goal-copy"><b>${g.label}</b><small>${g.sub}</small></span><span class="goal-reward">${g.done?'DONE':g.reward}</span></div>`).join('') }
function canCraft(r){return Object.entries(r.needs).every(([key,count])=>state.supplies[key]>=count)}
function craft(id){
 const r=recipes.find(x=>x.id===id);if(!r||!canCraft(r)){notify('You need a few more supplies for that one.');return}
 for(const [key,count] of Object.entries(r.needs))state.supplies[key]-=count;
 state.goods.unshift({id:Date.now()+Math.random(),recipe:r.id,price:r.price});state.made++;
 const order=state.orders.find(o=>o.recipe===r.id);$('#market-message').textContent=order?`${order.customer} is hoping for a ${r.name.toLowerCase()}!`:`A fresh ${r.name.toLowerCase()} is ready for the shelf.`;
 save();render();notify(`${r.emoji} ${r.name} made by hand!`);
}

input.newString:
 save();render();notify(`${r.emoji} ${r.name} made by hand!`);
}
function sellGood(id){
 const index=state.goods.findIndex(g=>String(g.id)===id);if(index<0)return;
 const [good]=state.goods.splice(index,1), recipe=recipes.find(r=>r.id===good.recipe), orderIndex=state.orders.findIndex(o=>o.recipe===good.recipe);
 if(orderIndex>=0){const order=state.orders.splice(orderIndex,1)[0];state.cash+=order.reward;state.rep++;state.sold++;state.visitors++;showCustomer(order.emoji);$('#market-message').textContent=`${order.customer} loves their ${recipe.name.toLowerCase()}!`;notify(`Wish fulfilled! ${money(order.reward)} and +1 neighborhood rep ♡`);addOrder();}
 else {state.cash+=good.price;state.sold++;state.visitors++;showCustomer();$('#market-message').textContent=`A happy neighbor found a ${recipe.name.toLowerCase()}!`;notify(`${recipe.emoji} Sold for ${money(good.price)}. Lovely!`)}
 save();render();
}
function sellAll(){if(!state.goods.length){notify('Make a little something first!');return}const ids=state.goods.map(g=>String(g.id));ids.forEach(sellGood);}
function showCustomer(emoji){const lane=$('#customer-lane'),figure=document.createElement('span');figure.className='customer';figure.textContent=emoji||['🧑🏻','👩🏽','👨🏼','👩🏻‍🦰'][Math.floor(Math.random()*4)];lane.append(figure);setTimeout(()=>figure.remove(),4500)}
function addCustomer(){if(state.orders.length<3)addOrder();state.visitors++;showCustomer();if(state.visitors%3===0)$('#market-message').textContent='The neighborhood is starting to notice your little shop!';$('#visitor-count').textContent=state.visitors;save();renderOrders()}
function endDay(){
 const bonus=8+Math.min(state.rep,12);state.cash+=bonus;state.day++;state.visitors=0;state.orders=[];makeOrders();
 $('#market-message').textContent=`Day ${state.day} is here! The morning sun is lovely.`;$('#customer-lane').innerHTML='';save();render();notify(`New day! You earned ${money(bonus)} for opening your shop.`);
}
function showRestock(){
 const options=[['starter','✿','Little basket','A few of everything to get making.','20',{wax:2,herbs:1,cloth:2,thread:2,wool:1,berries:2,jar:1,flowers:1,clay:1,glaze:1}],['textiles','🧶','Thread & textiles','Cotton, thread, and wool for soft things.','16',{cloth:4,thread:4,wool:3}],['garden','🌿','Garden gather','Herbs, berries, flowers, and beeswax.','14',{wax:3,herbs:3,berries:3,flowers:3}],['pottery','🏺','Potter’s bundle','Clay and glaze for little keepsakes.','12',{clay:4,glaze:3}]];
 $('#modal').innerHTML=`<p class="eyebrow">A QUICK TRIP TO THE SUPPLY MARKET</p><h2>Restock your basket</h2><p>Good materials make good things. Pick a bundle and get right back to making.</p><div class="modal-options">${options.map(([id,icon,name,desc,price])=>`<button class="upgrade-option" data-bundle="${id}" ${state.cash<price?'disabled':''}><span>${icon}</span><div><b>${name}</b><small>${desc}</small></div><strong>$${price}</strong></button>`).join('')}</div><div class="modal-actions"><button class="modal-close" data-close>Maybe later</button></div>`;
 $('#modal').querySelectorAll('[data-bundle]').forEach(btn=>btn.onclick=()=>buyBundle(btn.dataset.bundle,options));wireClose();$('#modal-backdrop').classList.add('show');
}
function buyBundle(id,options){const bundle=options.find(o=>o[0]===id);if(!bundle||state.cash<Number(bundle[4]))return;state.cash-=Number(bundle[4]);Object.entries(bundle[5]).forEach(([key,n])=>state.supplies[key]+=n);save();render();closeModal();notify('Supplies restocked. Time to make something! ✂')}
function showUpgrade(){
 const list=[
  {id:'sign',icon:'🪧',name:'A hand-painted sign',desc:'Raise every sale by $2.',price:45},
  {id:'shelf',icon:'🪴',name:'A charming display shelf',desc:'Every sale earns +1 neighborhood rep.',price:65},
  {id:'tea',icon:'🫖',name:'Tea for the road',desc:'Daily opening bonus +$8.',price:55}
 ];
 $('#modal').innerHTML=`<p class="eyebrow">MAKE YOUR LITTLE SHOP EVEN LOVELIER</p><h2>Workshop upgrades</h2><p>Small touches bring the whole neighborhood by.</p><div class="modal-options">${list.map(u=>`<button class="upgrade-option" data-upgrade="${u.id}" ${state.upgrades[u.id]||state.cash<u.price?'disabled':''}><span>${u.icon}</span><div><b>${u.name}${state.upgrades[u.id]?' · owned':''}</b><small>${u.desc}</small></div><strong>${state.upgrades[u.id]?'✓':'$'+u.price}</strong></button>`).join('')}</div><div class="modal-actions"><button class="modal-close" data-close>Close</button></div>`;
 $('#modal').querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>{const u=list.find(x=>x.id===btn.dataset.upgrade);if(!u||state.upgrades[u.id]||state.cash<u.price)return;state.cash-=u.price;state.upgrades[u.id]=true;save();render();showUpgrade();notify(`${u.name} added!`)});wireClose();$('#modal-backdrop').classList.add('show');
}
function wireClose(){$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function closeModal(){$('#modal-backdrop').classList.remove('show')}
function confirmReset(){
 $('#modal').innerHTML='<p class="eyebrow">A FRESH LITTLE START</p><h2>Start over?</h2><p>Your workshop, savings, and keepsakes will be reset. You can always grow a new garden.</p><div class="modal-actions"><button class="modal-close" data-close>Keep playing</button><button class="danger-btn" id="confirm-reset">Start fresh</button></div>';
 wireClose();$('#modal-backdrop').classList.add('show');$('#confirm-reset').onclick=()=>{localStorage.removeItem('littleWorkshopSave');state=structuredClone(initialState);makeOrders();save();render();closeModal();notify('A fresh new workshop awaits! ✿')};
}
$('#goal-list').addEventListener('click',showUpgrade);
setup();

