height:31px}
.game-grid{
gap:10px}
.market-panel{
padding:15px 13px 0}
.panel-heading h1{
font-size:22px}
.weather{
gap:4px}
.weather>span{
font-size:20px}
.weather b{
font-size:9px}
.weather small{
font-size:8px}
.market-scene{
height:240px;
margin:12px -13px 0}
.shop-roof{
width:86%}
.shop-front{
width:78%}
.planter-left{
left:4%}
.planter-right{
right:4%}
.customer-lane{
