gap:10px}
.orders-panel,.craft-panel,.inventory-panel,.progress-panel{
padding:14px}
.orders-panel{
min-height:auto}
.craft-panel{
min-height:0}
.orders-list{
margin-top:9px}
.order-card{
padding:8px}
.bottom-grid{
gap:10px;
margin-top:10px}
.goods-card{
min-width:125px}
.progress-panel{
padding-bottom:17px}
footer{
font-size:8px;
